-- la leçon d’un SECOND quiz venu d’ailleurs — le hub de leçon lit son quiz en
-- .maybeSingle(), deux quiz feraient lever « multiple rows » à de vrais élèves.
INSERT INTO public.quizzes (id, title, subject, grade_level, chapter, is_free, lesson_id)
SELECT v.id, v.title, v.subject, v.grade_level, v.chapter, true, l.id
  FROM (VALUES
    ('49e935af-d743-5a0d-a7c8-0321f0751546'::uuid, 'Quiz — Une seule espèce, ou plusieurs', 'Physique-Chimie', '2de', 'Corps purs et mélanges', '760bfa5a-f958-543b-be18-dbea5dd2d410'::uuid),
    ('7c77181e-bfcf-5172-9872-aaaf34a69cb0'::uuid, 'Quiz — Dire combien il y en a dans combien', 'Physique-Chimie', '2de', 'Composition d’un mélange', '0486ab71-7d4f-563d-8fb5-e6103b19c9b3'::uuid),
    ('bf2a3d20-1043-5302-bc47-d14af3802d75'::uuid, 'Quiz — Reconnaître ce qu’on a dans le tube', 'Physique-Chimie', '2de', 'Identification d’une espèce chimique', 'ac369fd0-2797-5ac4-891c-e4482dc3df71'::uuid),
    ('5d4ddce3-bdd7-567d-b9f6-63c0a150a9a3'::uuid, 'Quiz — Ce qu’il y a dans le noyau, et pourquoi ça compte', 'Physique-Chimie', '2de', 'Le noyau de l’atome', 'f979ab64-7b20-5f1d-9976-ede8937d1df5'::uuid),
    ('66049358-01e2-5902-9c46-bf32a19379d1'::uuid, 'Quiz — Ranger les électrons pour prévoir la chimie', 'Physique-Chimie', '2de', 'Configuration électronique d’un atome', '7b11d35a-4ad7-5ed3-bf10-b9fe7dd1b1b1'::uuid),
    ('2298c05c-8b8e-51db-9d6a-ec36dca4f9f3'::uuid, 'Quiz — Pourquoi les atomes s’associent', 'Physique-Chimie', '2de', 'Stabilité et charge électrique d’une entité chimique', 'ae34cbc6-c698-5871-abcc-5ed74e11e1ab'::uuid),
    ('74210253-26d8-5975-9b25-c309161baabf'::uuid, 'Quiz — La mole, ou comment peser des atomes', 'Physique-Chimie', '2de', 'Compter les entités dans un échantillon de matière', 'dd871be7-a98d-50a7-9aaa-a5c170cdc2ba'::uuid),
    ('cf5f302b-4492-54aa-a751-9ee23ecb5a91'::uuid, 'Quiz — Ce qui change, et ce qui ne change pas', 'Physique-Chimie', '2de', 'Caractéristiques et représentation d’un changement d’état', '2a53abfb-786c-5eb1-9cd4-3f058c16c301'::uuid),
    ('ef8f4ce6-70e7-5ad2-90b6-9266cccce620'::uuid, 'Quiz — Équilibrer, puis suivre ce qui disparaît', 'Physique-Chimie', '2de', 'Écriture et analyse d’une réaction chimique', '3999d985-e0a8-56d2-ac19-8a6df240b246'::uuid),
    ('bde8a934-13ed-5f49-8eb7-7f3955c9196c'::uuid, 'Quiz — Fabriquer au laboratoire ce que la nature produit', 'Physique-Chimie', '2de', 'Synthèse d’une espèce chimique présente dans la nature', 'ed068b25-24aa-5c03-b328-38c85591c09a'::uuid),
    ('0fcb9588-2abb-5a46-a23a-ed9e3227e5bf'::uuid, 'Quiz — Quand c’est le noyau qui change', 'Physique-Chimie', '2de', 'Identifier une réaction nucléaire', '490933d0-e38b-5b1c-92a1-a7a2cbcd5e0d'::uuid),
    ('a4f4e8d2-57f0-5dab-be73-1eecd72ad53f'::uuid, 'Quiz — Il n’y a pas de mouvement sans référentiel', 'Physique-Chimie', '2de', 'Relativité du mouvement', '31286f85-3eaa-5c6e-bb8f-b3fbba0c05ea'::uuid),
    ('c5f2474d-dfae-561f-b07e-79cc871cc693'::uuid, 'Quiz — Une flèche qui dit tout du mouvement', 'Physique-Chimie', '2de', 'Représentation et variation d’un vecteur vitesse', '91ef7a01-ad7e-5d4b-9bf5-84524f73ce08'::uuid),
    ('535f746f-f350-5d59-a296-74ad269a753a'::uuid, 'Quiz — Représenter ce qui agit sur un système', 'Physique-Chimie', '2de', 'Modélisation d’une action par une force', 'e52623b7-bf5c-56fb-9c6e-f4a787534523'::uuid),
    ('90ce17e6-fbc7-506b-9e50-d425f48221b7'::uuid, 'Quiz — Ce qui se passe quand les forces se compensent', 'Physique-Chimie', '2de', 'Le principe d’inertie', 'e9f3d76c-5db7-5674-a0aa-bf895cebae27'::uuid),
    ('f18dd46f-b39c-54d4-aa9b-da1ba95b610c'::uuid, 'Quiz — Ce qui vibre, ce qui transporte, ce qui reçoit', 'Physique-Chimie', '2de', 'Émission et propagation d’un signal sonore', '33b8be8f-52b4-56ff-a7d2-5d983eb7671f'::uuid),
    ('e1c5de6c-8e51-5460-8baa-dc232bb2012c'::uuid, 'Quiz — De la grandeur physique à la sensation', 'Physique-Chimie', '2de', 'Les sons : fréquence, intensité et perception', '551db1b6-5e58-5261-a662-2bc9b1a690c4'::uuid),
    ('29c584a1-8a28-53ca-a454-a0b915b7128b'::uuid, 'Quiz — Deux lois pour lire n’importe quel circuit', 'Physique-Chimie', '2de', 'Intensité et tension dans un circuit complexe', '83427e88-c7a6-5e03-8378-62e79020bdd6'::uuid),
    ('ef6df1ec-ca17-51a7-a186-a2c45f0eb894'::uuid, 'Quiz — Une droite, une pente, une résistance', 'Physique-Chimie', '2de', 'La loi d’Ohm et la résistance au courant électrique', '8fb18f9a-02eb-5c72-a9ff-a70c8c9cb794'::uuid),
    ('3e96bdc3-33b3-581f-8ede-b6bd8e01437f'::uuid, 'Quiz — Des rayons droits, et un blanc qui n’est pas une couleur', 'Physique-Chimie', '2de', 'Propagation et décomposition de la lumière', '5d465dee-305b-5892-a1bc-f0226cc37425'::uuid),
    ('84a0e71f-c02f-591e-ab52-90414eb7246f'::uuid, 'Quiz — Ce qui arrive à un rayon qui change de milieu', 'Physique-Chimie', '2de', 'Réflexion et réfraction de la lumière, le prisme', '1eac1cc8-fded-53ce-842b-7fd98077b728'::uuid),
    ('4c3e78d3-37e4-59ca-8617-c5e4325667d5'::uuid, 'Quiz — Un morceau de verre qui rassemble la lumière', 'Physique-Chimie', '2de', 'Les lentilles convergentes', '8233c12c-2154-5137-b782-2b316b590e88'::uuid),
    ('ac1fe737-4bf3-5679-a45c-cf4dc3cf21c9'::uuid, 'Quiz — Tracer, mesurer, vérifier par le calcul', 'Physique-Chimie', '2de', 'Construction de l’image d’un objet', 'a5c53fb3-2b9e-5932-aeab-32de05178cb0'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('b364b2b4-81fe-531c-b6a5-a497d022201c'::uuid, '49e935af-d743-5a0d-a7c8-0321f0751546'::uuid, 'Qu’est-ce qu’un corps pur ?', 'mcq', '["Une matière constituée d’une seule espèce chimique","Une matière sans impureté visible","Un mélange homogène","Une matière solide"]'::jsonb, 0, 'Il possède des températures de changement d’état bien définies.', 1),
    ('0f1fad8d-359e-53d8-9818-42dad7179f51'::uuid, '49e935af-d743-5a0d-a7c8-0321f0751546'::uuid, 'Qu’est-ce qu’un mélange homogène ?', 'mcq', '["Un mélange dont on ne distingue pas les constituants, même après repos","Un mélange de deux solides","Un mélange qui se sépare tout seul","Un mélange coloré"]'::jsonb, 0, 'Il ne comporte qu’une seule phase.', 2),
    ('27c29f0c-13a1-54ca-b698-89582d7601a3'::uuid, '49e935af-d743-5a0d-a7c8-0321f0751546'::uuid, 'Sous pression atmosphérique normale, à quelle température l’eau pure bout-elle ?', 'mcq', '["100 °C","0 °C","80 °C","120 °C"]'::jsonb, 0, 'La température reste constante durant l’ébullition.', 3),
    ('1edb3969-3935-559a-862e-d4fb857cc66c'::uuid, '49e935af-d743-5a0d-a7c8-0321f0751546'::uuid, 'Quelle technique sépare deux liquides ayant des températures d’ébullition différentes ?', 'mcq', '["La distillation","La filtration","La décantation","La centrifugation"]'::jsonb, 0, 'On récupère le distillat au condenseur.', 4),
    ('ddda86f2-f132-50e7-aad1-ddd599b1d653'::uuid, '49e935af-d743-5a0d-a7c8-0321f0751546'::uuid, 'Quelle est l’expression de la masse volumique ?', 'mcq', '["ρ = m / V","ρ = V / m","ρ = m × V","ρ = m + V"]'::jsonb, 0, 'Elle s’exprime par exemple en g·cm⁻³.', 5),
    ('eb2551dd-b7a6-5a15-b654-f5723545cfea'::uuid, '49e935af-d743-5a0d-a7c8-0321f0751546'::uuid, 'Que vaut la densité d’un corps par rapport à l’eau, s’il flotte ?', 'mcq', '["Elle est inférieure à 1","Elle est supérieure à 1","Elle vaut exactement 1","Elle est négative"]'::jsonb, 0, 'La densité est un nombre sans unité.', 6),
    ('f70a7db3-e4e8-567d-b927-a57730b0350f'::uuid, '49e935af-d743-5a0d-a7c8-0321f0751546'::uuid, 'La masse volumique d’un corps pur dépend de la quantité prélevée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une grandeur caractéristique, indépendante de la quantité.', 7),
    ('77b5fb68-4a4c-5457-af0d-ebcaeab3147d'::uuid, '49e935af-d743-5a0d-a7c8-0321f0751546'::uuid, 'Quelle technique permet de retenir un solide en suspension dans un liquide ?', 'mcq', '["La filtration","La distillation","L’évaporation","La chromatographie"]'::jsonb, 0, 'Le solide reste sur le filtre, le liquide passe.', 8),
    ('103c837e-6d52-55fd-aa49-401c96412bb3'::uuid, '7c77181e-bfcf-5172-9872-aaaf34a69cb0'::uuid, 'Dans une solution, quelle espèce appelle-t-on le solvant ?', 'mcq', '["L’espèce majoritaire, dans laquelle se dissout le soluté","L’espèce dissoute","L’espèce colorée","L’espèce solide"]'::jsonb, 0, 'Quand c’est l’eau, la solution est dite aqueuse.', 1),
    ('4df24c3c-487f-508a-83fa-04821ff4dff3'::uuid, '7c77181e-bfcf-5172-9872-aaaf34a69cb0'::uuid, 'Quelle est l’expression de la concentration en masse ?', 'mcq', '["t = m / V","t = V / m","t = m × V","t = m − V"]'::jsonb, 0, 'V est le volume de la solution obtenue.', 2),
    ('fa4daac8-0507-532f-9e2a-42acff9be930'::uuid, '7c77181e-bfcf-5172-9872-aaaf34a69cb0'::uuid, 'Quelle verrerie utilise-t-on pour préparer un volume précis de solution ?', 'mcq', '["La fiole jaugée","Le bécher","L’éprouvette graduée","L’erlenmeyer"]'::jsonb, 0, 'On complète jusqu’au trait de jauge.', 3),
    ('8904d255-52df-5f07-8571-d545e019e901'::uuid, '7c77181e-bfcf-5172-9872-aaaf34a69cb0'::uuid, 'Que conserve-t-on lors d’une dilution ?', 'mcq', '["La quantité de soluté","Le volume","La concentration","La masse volumique"]'::jsonb, 0, 'D’où la relation t₁ × V₁ = t₂ × V₂.', 4),
    ('dac5b546-d14c-57af-b4eb-c9ea7d0ed53f'::uuid, '7c77181e-bfcf-5172-9872-aaaf34a69cb0'::uuid, 'Comment prépare-t-on une dilution au dixième ?', 'mcq', '["On prélève 10,0 mL de solution mère et on complète à 100,0 mL","On ajoute 100 mL d’eau à 10 mL de solution","On prélève 1 mL et on complète à 10 L","On divise la masse de soluté par dix"]'::jsonb, 0, 'Le facteur de dilution vaut alors 10.', 5),
    ('139057b9-2ca0-5e57-8296-89541016a9a0'::uuid, '7c77181e-bfcf-5172-9872-aaaf34a69cb0'::uuid, 'Qu’est-ce qu’une solution saturée ?', 'mcq', '["Une solution qui ne peut plus dissoudre de soluté","Une solution très colorée","Une solution chauffée","Une solution filtrée"]'::jsonb, 0, 'La solubilité dépend de la température.', 6),
    ('30d6d033-e8aa-5ccd-b84d-e13c7e55aec4'::uuid, '7c77181e-bfcf-5172-9872-aaaf34a69cb0'::uuid, 'Quelle grandeur mesure-t-on au spectrophotomètre pour un dosage par étalonnage ?', 'mcq', '["L’absorbance","La masse","La température","La pression"]'::jsonb, 0, 'On la compare à une gamme d’étalons.', 7),
    ('6f86faee-1a30-5311-abe2-c0885beb5917'::uuid, '7c77181e-bfcf-5172-9872-aaaf34a69cb0'::uuid, 'L’air contient environ 21 % de dioxygène en volume.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec environ 78 % de diazote.', 8),
    ('c33138ee-dcac-5b66-a9d4-b426e6b46c70'::uuid, 'bf2a3d20-1043-5302-bc47-d14af3802d75'::uuid, 'Quel gaz rallume une bûchette incandescente ?', 'mcq', '["Le dioxygène","Le dioxyde de carbone","Le dihydrogène","Le diazote"]'::jsonb, 0, 'Le dioxyde de carbone, lui, trouble l’eau de chaux.', 1),
    ('a43273d3-2435-56cb-849b-a05ea18f387a'::uuid, 'bf2a3d20-1043-5302-bc47-d14af3802d75'::uuid, 'Quel test caractérise la présence d’eau ?', 'mcq', '["Le sulfate de cuivre anhydre passe du blanc au bleu","L’eau de chaux se trouble","Une détonation se produit","Un précipité rouille apparaît"]'::jsonb, 0, 'C’est un test simple et réversible par chauffage.', 2),
    ('37d19d12-8ac9-5681-ad37-c609ea4347a3'::uuid, 'bf2a3d20-1043-5302-bc47-d14af3802d75'::uuid, 'Quelle couleur a le précipité obtenu avec la soude en présence d’ions fer III ?', 'mcq', '["Rouille","Bleu","Vert","Blanc"]'::jsonb, 0, 'Le fer II donne un précipité vert, le cuivre II un précipité bleu.', 3),
    ('28aa6a90-40d1-5b63-b21b-53ef0263f353'::uuid, 'bf2a3d20-1043-5302-bc47-d14af3802d75'::uuid, 'Que met en évidence le nitrate d’argent ?', 'mcq', '["Les ions chlorure, par un précipité blanc qui noircit à la lumière","Les ions cuivre","Le dioxygène","L’eau"]'::jsonb, 0, 'Le noircissement est dû à la photosensibilité du chlorure d’argent.', 4),
    ('db5a973f-8560-587d-bea7-ead2816cafc9'::uuid, 'bf2a3d20-1043-5302-bc47-d14af3802d75'::uuid, 'Comment calcule-t-on le rapport frontal Rf ?', 'mcq', '["Distance parcourue par la tache divisée par la distance parcourue par le front d’éluant","Distance du front divisée par la distance de la tache","Masse de l’espèce divisée par le volume","Hauteur de la plaque divisée par sa largeur"]'::jsonb, 0, 'Rf est compris entre 0 et 1.', 5),
    ('720f81f4-f7b1-5643-85a8-7e5d20dbdbd0'::uuid, 'bf2a3d20-1043-5302-bc47-d14af3802d75'::uuid, 'Que conclut-on si deux dépôts migrent à la même hauteur en chromatographie ?', 'mcq', '["Il s’agit probablement de la même espèce chimique","Ils ont la même masse","Ils ont la même couleur","Ils sont de concentration égale"]'::jsonb, 0, 'Dans le même couple support-éluant.', 6),
    ('9a5abc9d-c4a3-5b9b-9d8d-00642503acde'::uuid, 'bf2a3d20-1043-5302-bc47-d14af3802d75'::uuid, 'Quel appareil permet de mesurer la température de fusion d’un solide ?', 'mcq', '["Le banc Kofler","Le spectrophotomètre","Le réfractomètre","La burette"]'::jsonb, 0, 'La température de fusion est une grandeur caractéristique.', 7),
    ('70a56b74-1bdc-5f49-85c3-686f7b8806b1'::uuid, 'bf2a3d20-1043-5302-bc47-d14af3802d75'::uuid, 'Une seule mesure suffit à identifier avec certitude une espèce chimique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On croise plusieurs indices, et toute mesure porte une incertitude.', 8),
    ('6e3149da-dbc8-5f95-993c-bc5fac2a88e3'::uuid, '5d4ddce3-bdd7-567d-b9f6-63c0a150a9a3'::uuid, 'Que désigne le numéro atomique Z ?', 'mcq', '["Le nombre de protons du noyau","Le nombre de nucléons","Le nombre de neutrons","Le nombre d’électrons de la couche externe"]'::jsonb, 0, 'Il définit l’élément chimique.', 1),
    ('c39bddbd-2be7-5e2e-b24e-7424a7c85236'::uuid, '5d4ddce3-bdd7-567d-b9f6-63c0a150a9a3'::uuid, 'Comment obtient-on le nombre de neutrons d’un noyau ?', 'mcq', '["En calculant A − Z","En calculant A + Z","En calculant Z − A","En divisant A par Z"]'::jsonb, 0, 'A est le nombre total de nucléons.', 2),
    ('89cabcbb-cbc4-5c9a-85db-427c85d4f580'::uuid, '5d4ddce3-bdd7-567d-b9f6-63c0a150a9a3'::uuid, 'Que sont deux isotopes ?', 'mcq', '["Deux noyaux de même Z mais de A différents","Deux noyaux de même A mais de Z différents","Deux atomes de charges opposées","Deux ions du même élément"]'::jsonb, 0, 'Ils ont les mêmes propriétés chimiques.', 3),
    ('94c77448-589e-5b8e-b5b1-c9a0b981828c'::uuid, '5d4ddce3-bdd7-567d-b9f6-63c0a150a9a3'::uuid, 'Quel est l’ordre de grandeur du diamètre d’un atome ?', 'mcq', '["10⁻¹⁰ m","10⁻¹⁵ m","10⁻⁶ m","10⁻³ m"]'::jsonb, 0, 'Le noyau, lui, mesure environ 10⁻¹⁵ m.', 4),
    ('69e7a96a-d2ec-5623-9996-a5ab4c91aa1b'::uuid, '5d4ddce3-bdd7-567d-b9f6-63c0a150a9a3'::uuid, 'Pourquoi dit-on que l’atome a une structure lacunaire ?', 'mcq', '["Parce que le noyau est 100 000 fois plus petit que l’atome","Parce qu’il lui manque des électrons","Parce qu’il contient des trous","Parce qu’il est instable"]'::jsonb, 0, 'L’essentiel du volume de l’atome est vide.', 5),
    ('44dcc84c-bde8-52fb-822b-f6494115517e'::uuid, '5d4ddce3-bdd7-567d-b9f6-63c0a150a9a3'::uuid, 'Où se trouve l’essentiel de la masse d’un atome ?', 'mcq', '["Dans le noyau","Dans le nuage électronique","Répartie uniformément","Dans les neutrons uniquement"]'::jsonb, 0, 'Un nucléon est environ 1 800 fois plus massif qu’un électron.', 6),
    ('50e3e74d-efb2-5eec-a10a-8a58610b301c'::uuid, '5d4ddce3-bdd7-567d-b9f6-63c0a150a9a3'::uuid, 'Un atome qui perd un électron devient un anion.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il devient un cation, de charge positive.', 7),
    ('aa06b1a0-4839-58aa-8f07-4f789c0493b3'::uuid, '5d4ddce3-bdd7-567d-b9f6-63c0a150a9a3'::uuid, 'Que vaut la charge élémentaire e ?', 'mcq', '["1,6 × 10⁻¹⁹ C","9,1 × 10⁻³¹ C","6,02 × 10²³ C","3,0 × 10⁸ C"]'::jsonb, 0, 'Le proton porte +e, l’électron −e.', 8),
    ('34b24d82-f1bd-5202-a075-fdd384efe7d5'::uuid, '66049358-01e2-5902-9c46-bf32a19379d1'::uuid, 'Combien d’électrons au maximum une sous-couche s peut-elle contenir ?', 'mcq', '["2","6","8","10"]'::jsonb, 0, 'Une sous-couche p en contient au maximum 6.', 1),
    ('99326a5f-6cfb-52a9-b260-0139608fe75b'::uuid, '66049358-01e2-5902-9c46-bf32a19379d1'::uuid, 'Quelle est la configuration électronique de l’oxygène (Z = 8) ?', 'mcq', '["1s² 2s² 2p⁴","1s² 2s² 2p⁶","1s² 2s⁴ 2p²","1s² 2s² 2p² 3s²"]'::jsonb, 0, 'Huit électrons répartis par énergie croissante.', 2),
    ('2577c397-7b3e-5b12-bd6f-5296d6b98af1'::uuid, '66049358-01e2-5902-9c46-bf32a19379d1'::uuid, 'Qu’appelle-t-on électrons de valence ?', 'mcq', '["Les électrons de la couche externe","Tous les électrons de l’atome","Les électrons du noyau","Les électrons de la première couche"]'::jsonb, 0, 'Ce sont eux qui interviennent dans les réactions chimiques.', 3),
    ('938258ac-a135-5acb-b493-fecece2be2e7'::uuid, '66049358-01e2-5902-9c46-bf32a19379d1'::uuid, 'Comment le tableau périodique est-il ordonné aujourd’hui ?', 'mcq', '["Par numéro atomique croissant","Par masse volumique croissante","Par ordre alphabétique","Par température de fusion"]'::jsonb, 0, 'Mendeleïev l’avait d’abord ordonné par masse.', 4),
    ('a9062654-5663-57a8-b333-cf420f8daab1'::uuid, '66049358-01e2-5902-9c46-bf32a19379d1'::uuid, 'Que partagent les éléments d’une même colonne du tableau périodique ?', 'mcq', '["Le même nombre d’électrons de valence","La même masse atomique","Le même nombre de neutrons","Le même état physique"]'::jsonb, 0, 'D’où des propriétés chimiques semblables.', 5),
    ('da5a0a82-dbd0-5c9b-9440-49d28b75cb3b'::uuid, '66049358-01e2-5902-9c46-bf32a19379d1'::uuid, 'Quelle est la particularité des gaz nobles ?', 'mcq', '["Leur couche externe est saturée, ils sont chimiquement inertes","Ils perdent facilement un électron","Ils gagnent facilement un électron","Ils sont tous radioactifs"]'::jsonb, 0, 'Ils occupent la dernière colonne du tableau.', 6),
    ('4b009de3-97b7-52cf-9b21-772d61b85f4a'::uuid, '66049358-01e2-5902-9c46-bf32a19379d1'::uuid, 'Les alcalins de la première colonne perdent facilement un électron.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui explique leur grande réactivité.', 7),
    ('4864eb56-27df-5785-b5c6-268ac47e96b4'::uuid, '66049358-01e2-5902-9c46-bf32a19379d1'::uuid, 'Dans quel ordre remplit-on les sous-couches pour les 18 premiers éléments ?', 'mcq', '["1s, 2s, 2p, 3s, 3p","1s, 2p, 2s, 3p, 3s","1s, 2s, 3s, 2p, 3p","2s, 1s, 2p, 3s, 3p"]'::jsonb, 0, 'Par énergie croissante.', 8),
    ('0f607791-16b7-5764-9983-8cde4ca06691'::uuid, '2298c05c-8b8e-51db-9d6a-ec36dca4f9f3'::uuid, 'Que dit la règle de l’octet ?', 'mcq', '["Un atome tend à avoir huit électrons sur sa couche externe","Un atome tend à avoir huit protons","Un atome perd toujours huit électrons","Un atome forme huit liaisons"]'::jsonb, 0, 'La règle du duet vise deux électrons, pour les éléments légers.', 1),
    ('012e07af-1eb6-5aed-94aa-76fbf54925d4'::uuid, '2298c05c-8b8e-51db-9d6a-ec36dca4f9f3'::uuid, 'Quel ion le sodium (Z = 11) forme-t-il ?', 'mcq', '["Na⁺","Na⁻","Na²⁺","Na²⁻"]'::jsonb, 0, 'Il perd son unique électron de la couche 3s.', 2),
    ('2590a540-1eff-5cc4-8356-fbca7c980018'::uuid, '2298c05c-8b8e-51db-9d6a-ec36dca4f9f3'::uuid, 'Quel ion l’oxygène forme-t-il ?', 'mcq', '["O²⁻","O⁺","O²⁺","O⁻"]'::jsonb, 0, 'Il gagne deux électrons pour atteindre l’octet.', 3),
    ('bbed5112-7cd5-5a44-b153-4cc3fe3d9682'::uuid, '2298c05c-8b8e-51db-9d6a-ec36dca4f9f3'::uuid, 'Qu’est-ce qu’une liaison covalente ?', 'mcq', '["Le partage d’un doublet d’électrons entre deux atomes","Le transfert d’un électron d’un atome à l’autre","Une attraction entre deux ions","Une liaison entre deux noyaux"]'::jsonb, 0, 'Chaque atome apporte un électron au doublet partagé.', 4),
    ('3a933045-a87e-5241-9610-5a99ac680e09'::uuid, '2298c05c-8b8e-51db-9d6a-ec36dca4f9f3'::uuid, 'Combien de liaisons covalentes le carbone forme-t-il ?', 'mcq', '["Quatre","Deux","Trois","Une"]'::jsonb, 0, 'Il lui manque quatre électrons pour l’octet.', 5),
    ('486ef594-6bec-5a55-9428-24ca7299df96'::uuid, '2298c05c-8b8e-51db-9d6a-ec36dca4f9f3'::uuid, 'Qu’est-ce qu’un doublet non liant ?', 'mcq', '["Une paire d’électrons de valence non partagée","Une liaison double","Un électron célibataire","Une liaison ionique"]'::jsonb, 0, 'L’oxygène de la molécule d’eau en porte deux.', 6),
    ('3cd10b59-ab61-54ce-8d69-caedb7b8fec3'::uuid, '2298c05c-8b8e-51db-9d6a-ec36dca4f9f3'::uuid, 'Une molécule est électriquement neutre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Contrairement à un ion, qui porte une charge.', 7),
    ('e140b906-204b-5f56-a1b3-c66406e1093f'::uuid, '2298c05c-8b8e-51db-9d6a-ec36dca4f9f3'::uuid, 'Combien de liaisons l’azote forme-t-il habituellement ?', 'mcq', '["Trois","Deux","Quatre","Une"]'::jsonb, 0, 'Il lui manque trois électrons pour compléter son octet.', 8),
    ('53d2a79f-ac0b-54e1-b9f0-66e69166c8ff'::uuid, '74210253-26d8-5975-9b25-c309161baabf'::uuid, 'Que vaut la constante d’Avogadro ?', 'mcq', '["6,02 × 10²³ mol⁻¹","1,6 × 10⁻¹⁹ mol⁻¹","9,81 mol⁻¹","3,0 × 10⁸ mol⁻¹"]'::jsonb, 0, 'C’est le nombre d’entités contenues dans une mole.', 1),
    ('87915044-5206-5eef-95d3-dc8ad12ecfb7'::uuid, '74210253-26d8-5975-9b25-c309161baabf'::uuid, 'Quelle relation relie quantité de matière et nombre d’entités ?', 'mcq', '["n = N / N_A","n = N × N_A","n = N_A / N","n = N + N_A"]'::jsonb, 0, 'La quantité de matière s’exprime en moles.', 2),
    ('d779f4fb-12c6-571f-a623-34c8c7e92c40'::uuid, '74210253-26d8-5975-9b25-c309161baabf'::uuid, 'Quelle est la masse molaire de l’eau H₂O ?', 'mcq', '["18,0 g·mol⁻¹","16,0 g·mol⁻¹","20,0 g·mol⁻¹","34,0 g·mol⁻¹"]'::jsonb, 0, 'Soit 2 × 1,0 + 16,0.', 3),
    ('7dd0803d-e119-5c0e-b01c-5c5dd236081c'::uuid, '74210253-26d8-5975-9b25-c309161baabf'::uuid, 'Comment calcule-t-on une quantité de matière à partir d’une masse ?', 'mcq', '["n = m / M","n = m × M","n = M / m","n = m + M"]'::jsonb, 0, 'Avec m en grammes et M en g·mol⁻¹.', 4),
    ('01f25bec-ac4d-5227-aab3-f4ba31af786b'::uuid, '74210253-26d8-5975-9b25-c309161baabf'::uuid, 'Quelle quantité de matière représente 9,0 g d’eau ?', 'mcq', '["0,50 mol","1,0 mol","2,0 mol","0,25 mol"]'::jsonb, 0, 'n = 9,0 / 18,0 = 0,50 mol.', 5),
    ('8bbf4513-f237-5651-bd3e-534c103a2042'::uuid, '74210253-26d8-5975-9b25-c309161baabf'::uuid, 'Comment calcule-t-on la quantité de matière d’un gaz ?', 'mcq', '["n = V / V_m","n = V × V_m","n = V_m / V","n = V / M"]'::jsonb, 0, 'V_m vaut environ 24,0 L·mol⁻¹ à 20 °C sous 1 013 hPa.', 6),
    ('9f606e7f-63cb-51d8-9a20-6a191c8441f3'::uuid, '74210253-26d8-5975-9b25-c309161baabf'::uuid, 'La mole est une unité de masse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une unité de quantité de matière, donc un compte d’entités.', 7),
    ('90080ad9-bf12-5481-846a-c73e11cd9c0e'::uuid, '74210253-26d8-5975-9b25-c309161baabf'::uuid, 'Comment relie-t-on concentration en masse et concentration en quantité de matière ?', 'mcq', '["t = c × M","t = c / M","t = M / c","t = c + M"]'::jsonb, 0, 'M est la masse molaire du soluté.', 8),
    ('df344f8f-a1e3-5484-87b3-140337d81920'::uuid, 'cf5f302b-4492-54aa-a751-9ee23ecb5a91'::uuid, 'Comment appelle-t-on le passage de l’état solide à l’état gazeux ?', 'mcq', '["La sublimation","La fusion","La vaporisation","La liquéfaction"]'::jsonb, 0, 'Le passage inverse est la condensation solide.', 1),
    ('2b8191b2-8acc-5fd0-bdf6-d8730f4fa82a'::uuid, 'cf5f302b-4492-54aa-a751-9ee23ecb5a91'::uuid, 'Comment appelle-t-on le passage de l’état gazeux à l’état liquide ?', 'mcq', '["La liquéfaction","La vaporisation","La solidification","La sublimation"]'::jsonb, 0, 'C’est ce qui se produit sur une vitre froide.', 2),
    ('2226fef1-6cec-5620-b87a-03228c7e0965'::uuid, 'cf5f302b-4492-54aa-a751-9ee23ecb5a91'::uuid, 'Que se passe-t-il pour la température d’un corps pur pendant un changement d’état ?', 'mcq', '["Elle reste constante","Elle augmente régulièrement","Elle diminue","Elle varie de façon aléatoire"]'::jsonb, 0, 'C’est le palier de changement d’état.', 3),
    ('e16979ed-c5e4-590d-a4f2-07dfadcbba6e'::uuid, 'cf5f302b-4492-54aa-a751-9ee23ecb5a91'::uuid, 'Comment distinguer un corps pur d’un mélange à partir d’une courbe de chauffage ?', 'mcq', '["Le corps pur présente un palier net, pas le mélange","Le mélange chauffe plus vite","Le corps pur ne change pas d’état","Le mélange présente deux paliers"]'::jsonb, 0, 'C’est un critère expérimental simple.', 4),
    ('a262d63c-c38a-5783-84ea-76d558c49f10'::uuid, 'cf5f302b-4492-54aa-a751-9ee23ecb5a91'::uuid, 'La fusion est-elle endothermique ou exothermique ?', 'mcq', '["Endothermique : elle absorbe de l’énergie","Exothermique : elle libère de l’énergie","Ni l’un ni l’autre","Cela dépend du corps"]'::jsonb, 0, 'La solidification, elle, libère de l’énergie.', 5),
    ('d3cfb5c9-3f7c-5f2a-893e-1b625ac44660'::uuid, 'cf5f302b-4492-54aa-a751-9ee23ecb5a91'::uuid, 'Pourquoi la transpiration rafraîchit-elle ?', 'mcq', '["Parce que la vaporisation de l’eau prélève de l’énergie sur la peau","Parce que l’eau est froide","Parce que le vent souffle","Parce que la peau se dilate"]'::jsonb, 0, 'La vaporisation est endothermique.', 6),
    ('2c939d85-afbf-5c19-9258-5853339ddf24'::uuid, 'cf5f302b-4492-54aa-a751-9ee23ecb5a91'::uuid, 'Un changement d’état modifie la nature des molécules.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une transformation physique : seule l’organisation change.', 7),
    ('7bd17d5b-80b7-54c6-9383-ae92933358da'::uuid, 'cf5f302b-4492-54aa-a751-9ee23ecb5a91'::uuid, 'À quelle température l’eau bout-elle au sommet de l’Everest ?', 'mcq', '["Environ 70 °C","Exactement 100 °C","Environ 120 °C","Environ 0 °C"]'::jsonb, 0, 'La pression y est bien plus faible qu’au niveau de la mer.', 8),
    ('45f9bb32-80ae-5155-8a15-f39243971ccf'::uuid, 'ef8f4ce6-70e7-5ad2-90b6-9266cccce620'::uuid, 'Que garantit l’équilibrage d’une équation de réaction ?', 'mcq', '["La conservation des éléments et de la charge électrique","La conservation du volume","La conservation de la température","L’égalité des masses molaires"]'::jsonb, 0, 'Autant d’atomes de chaque élément de part et d’autre.', 1),
    ('59cfc252-fe47-5233-b81f-ebe08ada3c7c'::uuid, 'ef8f4ce6-70e7-5ad2-90b6-9266cccce620'::uuid, 'Quelle équation traduit correctement la combustion complète du méthane ?', 'mcq', '["CH₄ + 2 O₂ donne CO₂ + 2 H₂O","CH₄ + O₂ donne CO₂ + H₂O","CH₄ + 3 O₂ donne CO₂ + 2 H₂O","CH₄ + 2 O₂ donne CO + 2 H₂O"]'::jsonb, 0, 'Quatre atomes d’oxygène de chaque côté.', 2),
    ('fa925b70-3381-5d12-95bc-f5b957c78e30'::uuid, 'ef8f4ce6-70e7-5ad2-90b6-9266cccce620'::uuid, 'Que représente l’avancement x d’une réaction ?', 'mcq', '["Une quantité de matière, en moles, mesurant la progression de la réaction","Une vitesse de réaction","Une masse de produit","Une durée"]'::jsonb, 0, 'Il structure le tableau d’avancement.', 3),
    ('724bff0f-0094-5a86-ac4f-0ae560218c0f'::uuid, 'ef8f4ce6-70e7-5ad2-90b6-9266cccce620'::uuid, 'Qu’est-ce que le réactif limitant ?', 'mcq', '["Le réactif entièrement consommé en premier, qui arrête la réaction","Le réactif présent en plus grande quantité","Le réactif le plus cher","Le réactif ajouté en dernier"]'::jsonb, 0, 'Il fixe l’avancement maximal.', 4),
    ('666ba33a-b3fb-5f63-89d5-4f19c855aa41'::uuid, 'ef8f4ce6-70e7-5ad2-90b6-9266cccce620'::uuid, 'Qu’est-ce qu’un mélange stœchiométrique ?', 'mcq', '["Un mélange où tous les réactifs sont consommés en même temps","Un mélange de volumes égaux","Un mélange de masses égales","Un mélange sans réactif limitant identifiable"]'::jsonb, 0, 'Aucun réactif ne reste en excès.', 5),
    ('865ce8e8-2a76-5751-a48b-82c6f1dbb4b4'::uuid, 'ef8f4ce6-70e7-5ad2-90b6-9266cccce620'::uuid, 'Avec 1,0 mol de CH₄ et 1,0 mol de O₂, quel est le réactif limitant ?', 'mcq', '["Le dioxygène","Le méthane","Aucun, le mélange est stœchiométrique","Les deux à la fois"]'::jsonb, 0, 'Il s’annule pour x = 0,50 mol, contre 1,0 mol pour le méthane.', 6),
    ('5505c338-a1ad-57f3-b87a-00e256a264aa'::uuid, 'ef8f4ce6-70e7-5ad2-90b6-9266cccce620'::uuid, 'Une équation de réaction indique la vitesse à laquelle la réaction se produit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle indique seulement les proportions dans lesquelles les espèces réagissent.', 7),
    ('4b9459e3-faa9-5139-a097-757a72b2a52f'::uuid, 'ef8f4ce6-70e7-5ad2-90b6-9266cccce620'::uuid, 'Comment qualifie-t-on une réaction qui libère de l’énergie thermique ?', 'mcq', '["Exothermique","Endothermique","Athermique","Isotherme"]'::jsonb, 0, 'Les combustions en sont l’exemple classique.', 8),
    ('9c918985-47f4-5da8-b246-2157d01a3a6b'::uuid, 'bde8a934-13ed-5f49-8eb7-7f3955c9196c'::uuid, 'Une molécule de synthèse diffère-t-elle de la même molécule naturelle ?', 'mcq', '["Non, si sa structure est identique","Oui, toujours","Oui, elle est moins pure par nature","Oui, elle a une masse molaire différente"]'::jsonb, 0, 'L’organisme ne fait aucune différence.', 1),
    ('a052b4ca-4ee9-5ff9-90c4-98d691cf9f39'::uuid, 'bde8a934-13ed-5f49-8eb7-7f3955c9196c'::uuid, 'À quoi sert un chauffage à reflux ?', 'mcq', '["Chauffer sans perdre de matière, les vapeurs étant condensées et renvoyées","Refroidir le mélange réactionnel","Séparer deux liquides","Mesurer la température de fusion"]'::jsonb, 0, 'Il accélère la réaction sans perte.', 2),
    ('cc906e87-3101-5bbf-b26b-073eccd7f186'::uuid, 'bde8a934-13ed-5f49-8eb7-7f3955c9196c'::uuid, 'Quelles sont les trois grandes étapes d’une synthèse ?', 'mcq', '["Transformation, séparation, identification","Pesée, dissolution, filtration","Mesure, calcul, conclusion","Extraction, dilution, dosage"]'::jsonb, 0, 'Chacune a ses techniques propres.', 3),
    ('69f3c111-71c1-558c-8702-86b55829f7ed'::uuid, 'bde8a934-13ed-5f49-8eb7-7f3955c9196c'::uuid, 'Comment définit-on le rendement d’une synthèse ?', 'mcq', '["Le rapport de la quantité obtenue à la quantité maximale attendue","La masse de produit obtenue","Le rapport du volume au temps","Le rapport des masses molaires"]'::jsonb, 0, 'Il est toujours inférieur à 1.', 4),
    ('73b48a9a-65dc-5c01-920a-6c18dc6e72de'::uuid, 'bde8a934-13ed-5f49-8eb7-7f3955c9196c'::uuid, 'Pourquoi le rendement n’atteint-il jamais 100 % ?', 'mcq', '["Pertes aux transferts, réaction incomplète, réactions secondaires","Parce que les réactifs sont impurs par définition","Parce que la mole est une approximation","Parce que la balance est imprécise"]'::jsonb, 0, 'Plusieurs causes se cumulent.', 5),
    ('a5346d7e-32b3-5028-be6b-c224728dea52'::uuid, 'bde8a934-13ed-5f49-8eb7-7f3955c9196c'::uuid, 'Sur quoi repose une extraction par solvant ?', 'mcq', '["La différence de solubilité de l’espèce dans deux liquides non miscibles","La différence de température d’ébullition","La différence de masse molaire","La différence de couleur"]'::jsonb, 0, 'On sépare ensuite les phases par décantation.', 6),
    ('373adf83-f56e-522f-8981-cdf2c17bd3a0'::uuid, 'bde8a934-13ed-5f49-8eb7-7f3955c9196c'::uuid, 'Une espèce naturelle est nécessairement moins dangereuse qu’une espèce de synthèse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce qui compte est la molécule, sa dose et son usage.', 7),
    ('8e6349ef-5d20-5a76-aac6-1ecfe7c54557'::uuid, 'bde8a934-13ed-5f49-8eb7-7f3955c9196c'::uuid, 'Que trouve-t-on sur l’étiquette d’un flacon de produit chimique ?', 'mcq', '["Des pictogrammes de danger et des mentions H et P","Le rendement de synthèse","La quantité de matière","Le protocole complet"]'::jsonb, 0, 'Elles guident les précautions à prendre.', 8),
    ('8b941f37-5f78-5988-843f-23839825ef00'::uuid, '0fcb9588-2abb-5a46-a23a-ed9e3227e5bf'::uuid, 'Qu’est-ce qui distingue une réaction nucléaire d’une réaction chimique ?', 'mcq', '["Elle modifie le noyau et transforme un élément en un autre","Elle ne concerne que les électrons","Elle libère moins d’énergie","Elle conserve la charge des ions"]'::jsonb, 0, 'L’énergie mise en jeu est de l’ordre du million de fois plus grande.', 1),
    ('5fbf8a8d-ec25-5111-8b59-613bb6586549'::uuid, '0fcb9588-2abb-5a46-a23a-ed9e3227e5bf'::uuid, 'Que conservent les lois de Soddy ?', 'mcq', '["Le nombre de nucléons A et le nombre de charge Z","La masse et le volume","La température et la pression","Le nombre d’électrons"]'::jsonb, 0, 'Elles permettent de compléter une équation nucléaire.', 2),
    ('ab17d0e8-98c8-5e90-b522-3a5577b3601c'::uuid, '0fcb9588-2abb-5a46-a23a-ed9e3227e5bf'::uuid, 'Que se passe-t-il lors d’une désintégration α ?', 'mcq', '["Le noyau émet un noyau d’hélium : A diminue de 4, Z de 2","Le noyau émet un électron","Le noyau émet un positon","Le noyau se scinde en deux"]'::jsonb, 0, 'La particule α est un noyau d’hélium 4.', 3),
    ('bb35eb42-dd75-56f2-af91-043f5c62933d'::uuid, '0fcb9588-2abb-5a46-a23a-ed9e3227e5bf'::uuid, 'Que se passe-t-il lors d’une désintégration β⁻ ?', 'mcq', '["Un neutron devient un proton et un électron est émis : Z augmente de 1","Un proton devient un neutron","Le noyau perd deux protons","Le noyau émet un photon seulement"]'::jsonb, 0, 'Le nombre de nucléons A reste constant.', 4),
    ('8b828e77-0d87-51bb-afd7-4ca839049e72'::uuid, '0fcb9588-2abb-5a46-a23a-ed9e3227e5bf'::uuid, 'Qu’est-ce que le rayonnement γ ?', 'mcq', '["Un rayonnement électromagnétique très énergétique émis par un noyau qui se désexcite","Un noyau d’hélium","Un flux d’électrons","Un flux de neutrons"]'::jsonb, 0, 'Il accompagne souvent les désintégrations α et β.', 5),
    ('1110a2a3-4af3-5e4b-8582-f672a074bcb5'::uuid, '0fcb9588-2abb-5a46-a23a-ed9e3227e5bf'::uuid, 'Qu’est-ce que la fission nucléaire ?', 'mcq', '["La cassure d’un noyau lourd en noyaux plus légers","L’union de deux noyaux légers","L’émission d’un électron","La désexcitation d’un noyau"]'::jsonb, 0, 'C’est le principe des centrales nucléaires actuelles.', 6),
    ('6fa7c522-869d-5a3d-967c-18a7d46f52bd'::uuid, '0fcb9588-2abb-5a46-a23a-ed9e3227e5bf'::uuid, 'La fusion nucléaire est la source d’énergie des étoiles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle unit des noyaux légers, comme des isotopes de l’hydrogène.', 7),
    ('8482a3b2-c980-5b57-9c24-c606f48689d8'::uuid, '0fcb9588-2abb-5a46-a23a-ed9e3227e5bf'::uuid, 'Peut-on prévoir le moment exact où un noyau donné va se désintégrer ?', 'mcq', '["Non, seule une loi statistique apparaît sur un grand nombre de noyaux","Oui, avec précision","Oui, si l’on connaît sa masse","Oui, en le refroidissant"]'::jsonb, 0, 'La désintégration individuelle est imprévisible.', 8),
    ('f3bb6ac2-7e92-50ed-9356-87adb8d9fdb4'::uuid, 'a4f4e8d2-57f0-5dab-be73-1eecd72ad53f'::uuid, 'Qu’est-ce qu’un référentiel ?', 'mcq', '["Un objet de référence, muni d’un repère et d’une horloge","La trajectoire d’un objet","La vitesse d’un mobile","Un système d’unités"]'::jsonb, 0, 'Sans lui, décrire un mouvement n’a pas de sens.', 1),
    ('0e7cb489-e450-5f01-a4e7-b5e00a7a9bc6'::uuid, 'a4f4e8d2-57f0-5dab-be73-1eecd72ad53f'::uuid, 'Un passager assis dans un train est-il en mouvement ?', 'mcq', '["Cela dépend du référentiel choisi","Oui, toujours","Non, jamais","Seulement si le train accélère"]'::jsonb, 0, 'Immobile dans le référentiel du train, en mouvement dans celui du sol.', 2),
    ('7f8ec9b4-1031-5d83-9a73-a4943241c29c'::uuid, 'a4f4e8d2-57f0-5dab-be73-1eecd72ad53f'::uuid, 'Quel référentiel utilise-t-on pour étudier le mouvement des planètes ?', 'mcq', '["Le référentiel héliocentrique","Le référentiel terrestre","Le référentiel géocentrique","Le référentiel du laboratoire"]'::jsonb, 0, 'Le géocentrique sert aux satellites de la Terre.', 3),
    ('3d8e56a8-45ef-5f7a-a864-7709ee13dfe4'::uuid, 'a4f4e8d2-57f0-5dab-be73-1eecd72ad53f'::uuid, 'Qu’est-ce que la trajectoire d’un point ?', 'mcq', '["L’ensemble de ses positions successives dans un référentiel donné","La distance qu’il parcourt","Sa vitesse au cours du temps","Sa position initiale"]'::jsonb, 0, 'Elle change si l’on change de référentiel.', 4),
    ('a57c173e-6244-5544-a257-48d003617f29'::uuid, 'a4f4e8d2-57f0-5dab-be73-1eecd72ad53f'::uuid, 'Quelle courbe décrit la valve d’une roue de vélo pour un observateur au bord de la route ?', 'mcq', '["Une cycloïde","Un cercle","Une droite","Une parabole"]'::jsonb, 0, 'Pour le cycliste, elle décrit un cercle.', 5),
    ('96b8830c-575e-5851-ad50-c532bcca145d'::uuid, 'a4f4e8d2-57f0-5dab-be73-1eecd72ad53f'::uuid, 'Comment qualifie-t-on un mouvement dont la trajectoire est une droite et la vitesse constante ?', 'mcq', '["Rectiligne uniforme","Circulaire uniforme","Rectiligne accéléré","Curviligne ralenti"]'::jsonb, 0, 'Deux informations : la forme et l’évolution de la vitesse.', 6),
    ('d8d0a544-4067-5262-a342-f22a5dddae98'::uuid, 'a4f4e8d2-57f0-5dab-be73-1eecd72ad53f'::uuid, 'À combien de km·h⁻¹ correspond 1 m·s⁻¹ ?', 'mcq', '["3,6 km·h⁻¹","1,0 km·h⁻¹","0,36 km·h⁻¹","36 km·h⁻¹"]'::jsonb, 0, 'On multiplie par 3,6 pour passer des m·s⁻¹ aux km·h⁻¹.', 7),
    ('6dcaf8a6-25f0-5c63-8fef-01d5a54da670'::uuid, 'a4f4e8d2-57f0-5dab-be73-1eecd72ad53f'::uuid, 'La trajectoire d’un objet est la même dans tous les référentiels.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle dépend du référentiel, comme le mouvement lui-même.', 8),
    ('3d2eb43a-25ba-57a0-b5cf-3d3d4798415c'::uuid, 'c5f2474d-dfae-561f-b07e-79cc871cc693'::uuid, 'Quelles sont les quatre caractéristiques d’un vecteur vitesse ?', 'mcq', '["Point d’application, direction, sens et valeur","Masse, vitesse, temps et distance","Origine, longueur, couleur et échelle","Position, trajectoire, durée et accélération"]'::jsonb, 0, 'La longueur de la flèche représente la valeur, à l’échelle.', 1),
    ('0b010c8d-7ee3-5632-befc-46c722f47ea8'::uuid, 'c5f2474d-dfae-561f-b07e-79cc871cc693'::uuid, 'Quelle est la direction du vecteur vitesse en un point ?', 'mcq', '["Celle de la tangente à la trajectoire","Celle de la corde entre deux points","Celle du rayon du cercle","Toujours horizontale"]'::jsonb, 0, 'Le sens est celui du mouvement.', 2),
    ('84a171a0-d67a-5e5e-9b13-fa18c2e3507a'::uuid, 'c5f2474d-dfae-561f-b07e-79cc871cc693'::uuid, 'Comment estime-t-on la vitesse au point M_i sur un enregistrement ?', 'mcq', '["En divisant la distance M_(i−1)M_(i+1) par 2 τ","En divisant M_iM_(i+1) par 2 τ","En multipliant la distance par la durée","En mesurant la longueur totale de la trajectoire"]'::jsonb, 0, 'τ est l’intervalle de temps entre deux positions successives.', 3),
    ('99e6558e-12c2-5b68-b224-7594d1ea3712'::uuid, 'c5f2474d-dfae-561f-b07e-79cc871cc693'::uuid, 'Comment construit-on graphiquement la variation du vecteur vitesse ?', 'mcq', '["On reporte les deux vecteurs depuis un même point et on joint leurs extrémités","On additionne leurs longueurs","On les superpose","On calcule leur moyenne"]'::jsonb, 0, 'La variation va de l’extrémité du vecteur initial à celle du final.', 4),
    ('18194fea-f9a6-51aa-932c-c3a9741a3796'::uuid, 'c5f2474d-dfae-561f-b07e-79cc871cc693'::uuid, 'Dans un mouvement rectiligne uniforme, que vaut la variation du vecteur vitesse ?', 'mcq', '["Elle est nulle","Elle est maximale","Elle pointe vers l’avant","Elle change de sens"]'::jsonb, 0, 'Ni la direction ni la valeur ne changent.', 5),
    ('4c20711a-b944-5546-ab7a-48b64621edc5'::uuid, 'c5f2474d-dfae-561f-b07e-79cc871cc693'::uuid, 'Dans un mouvement circulaire uniforme, la variation du vecteur vitesse est-elle nulle ?', 'mcq', '["Non, la direction change en permanence","Oui, la vitesse est constante","Oui, la trajectoire est fermée","Cela dépend du rayon"]'::jsonb, 0, 'Elle pointe vers l’intérieur du cercle.', 6),
    ('14ff1ead-a6f5-53d6-8bf5-95cb7aeca0de'::uuid, 'c5f2474d-dfae-561f-b07e-79cc871cc693'::uuid, 'Le vecteur variation de vitesse a le même sens que la somme des forces appliquées.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le lien entre cinématique et dynamique.', 7),
    ('96fac4f8-b20e-5f6e-beee-38ba64c9c535'::uuid, 'c5f2474d-dfae-561f-b07e-79cc871cc693'::uuid, 'Dans quelle unité s’exprime la valeur d’un vecteur vitesse dans le système international ?', 'mcq', '["En m·s⁻¹","En km·h⁻¹","En m·s⁻²","En newtons"]'::jsonb, 0, 'On convertit en km·h⁻¹ en multipliant par 3,6.', 8),
    ('ebc34c31-eab4-58a7-8bcf-c862608e32a1'::uuid, '535f746f-f350-5d59-a296-74ad269a753a'::uuid, 'Comment modélise-t-on une action mécanique ?', 'mcq', '["Par une force, représentée par un vecteur","Par une distance","Par une masse","Par une durée"]'::jsonb, 0, 'Point d’application, direction, sens et valeur en newtons.', 1),
    ('9cf33447-9f0e-558e-a72a-329be311c476'::uuid, '535f746f-f350-5d59-a296-74ad269a753a'::uuid, 'Quelle est l’unité de la valeur d’une force ?', 'mcq', '["Le newton","Le joule","Le pascal","Le kilogramme"]'::jsonb, 0, 'Symbole N.', 2),
    ('46af2cd2-3b05-5907-a2e1-988f5620f2e7'::uuid, '535f746f-f350-5d59-a296-74ad269a753a'::uuid, 'Quelle est l’expression du poids d’un objet ?', 'mcq', '["P = m × g","P = m / g","P = g / m","P = m + g"]'::jsonb, 0, 'Avec g ≈ 9,8 N·kg⁻¹ à la surface de la Terre.', 3),
    ('679f00a5-4a9b-59cf-999f-2822079e96ce'::uuid, '535f746f-f350-5d59-a296-74ad269a753a'::uuid, 'Quelle différence entre masse et poids ?', 'mcq', '["La masse est identique partout, le poids dépend du lieu","Le poids est identique partout","Ce sont deux mots pour la même grandeur","La masse se mesure en newtons"]'::jsonb, 0, 'Sur la Lune, g vaut environ 1,6 N·kg⁻¹.', 4),
    ('780c41f0-2cfa-515f-b90d-314b9676c227'::uuid, '535f746f-f350-5d59-a296-74ad269a753a'::uuid, 'Quelle est l’expression de la force d’interaction gravitationnelle ?', 'mcq', '["F = G × m_A × m_B / d²","F = G × m_A × m_B / d","F = G × d² / (m_A × m_B)","F = m_A × m_B × d²"]'::jsonb, 0, 'Elle décroît comme le carré de la distance.', 5),
    ('cc324cf4-59b3-5dc6-aa90-88ee4f9e5309'::uuid, '535f746f-f350-5d59-a296-74ad269a753a'::uuid, 'Que devient la force gravitationnelle si la distance double ?', 'mcq', '["Elle est divisée par quatre","Elle est divisée par deux","Elle est multipliée par deux","Elle ne change pas"]'::jsonb, 0, 'Le carré de la distance est au dénominateur.', 6),
    ('8cb37ec4-a639-5fd3-b986-77f6d510340e'::uuid, '535f746f-f350-5d59-a296-74ad269a753a'::uuid, 'Selon le principe des actions réciproques, les deux forces se compensent-elles ?', 'mcq', '["Non, elles ne s’appliquent pas au même objet","Oui, toujours","Oui, si les masses sont égales","Oui, si les corps sont immobiles"]'::jsonb, 0, 'Elles sont opposées mais appliquées à deux systèmes différents.', 7),
    ('dea0be1f-3bff-5bfd-a914-c6d318f3d25f'::uuid, '535f746f-f350-5d59-a296-74ad269a753a'::uuid, 'La force exercée par un fil sur un objet est une action à distance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une action de contact ; le poids est une action à distance.', 8),
    ('c70e1ac2-92a4-55f4-99e5-de2baf406b69'::uuid, '90ce17e6-fbc7-506b-9e50-d425f48221b7'::uuid, 'Que dit le principe d’inertie ?', 'mcq', '["Si les forces se compensent, le vecteur vitesse ne varie pas","Une force est nécessaire pour maintenir un mouvement","Tout corps finit par s’arrêter","La vitesse est proportionnelle à la force"]'::jsonb, 0, 'Le système est immobile ou en mouvement rectiligne uniforme.', 1),
    ('669d5ca7-6596-5bea-a598-cb6104ba97d1'::uuid, '90ce17e6-fbc7-506b-9e50-d425f48221b7'::uuid, 'Faut-il une force pour entretenir un mouvement rectiligne uniforme ?', 'mcq', '["Non, il en faut une pour le changer","Oui, sinon le mouvement cesse","Oui, proportionnelle à la vitesse","Cela dépend de la masse"]'::jsonb, 0, 'C’est l’erreur la plus tenace en mécanique.', 2),
    ('c6a6da70-83fa-5d4e-8299-76bc23d7f1ec'::uuid, '90ce17e6-fbc7-506b-9e50-d425f48221b7'::uuid, 'Que peut-on conclure si le vecteur vitesse d’un système varie ?', 'mcq', '["Les forces ne se compensent pas","Le référentiel n’est pas galiléen","La masse a changé","Le système est immobile"]'::jsonb, 0, 'La somme des forces a le même sens que la variation de vitesse.', 3),
    ('63c2eaca-bed4-54f3-a679-0e0d657835b5'::uuid, '90ce17e6-fbc7-506b-9e50-d425f48221b7'::uuid, 'Pourquoi une voiture à vitesse constante sur une route droite vérifie-t-elle le principe d’inertie ?', 'mcq', '["Parce que la force motrice compense exactement les frottements","Parce qu’elle n’est soumise à aucune force","Parce que son moteur est éteint","Parce que sa masse est constante"]'::jsonb, 0, 'La somme vectorielle des forces est nulle.', 4),
    ('556285b2-a2a1-5a3e-9158-b474947ac173'::uuid, '90ce17e6-fbc7-506b-9e50-d425f48221b7'::uuid, 'Qu’est-ce qu’un corps en chute libre ?', 'mcq', '["Un corps soumis à son seul poids","Un corps qui tombe dans l’air","Un corps lâché sans vitesse initiale","Un corps sans masse"]'::jsonb, 0, 'Toute autre force, comme la résistance de l’air, est négligée.', 5),
    ('a599101e-938b-5a36-bb8a-e8e132591698'::uuid, '90ce17e6-fbc7-506b-9e50-d425f48221b7'::uuid, 'Dans un tube où l’on a fait le vide, une plume et une bille tombent-elles ensemble ?', 'mcq', '["Oui, la masse n’intervient pas dans la chute libre","Non, la bille tombe plus vite","Non, la plume tombe plus vite","Cela dépend de la hauteur"]'::jsonb, 0, 'Dans l’air, c’est la résistance de l’air qui les sépare.', 6),
    ('b767e9ab-5fde-56f0-823b-fb8035a3e3e8'::uuid, '90ce17e6-fbc7-506b-9e50-d425f48221b7'::uuid, 'Le référentiel terrestre est une bonne approximation d’un référentiel galiléen pour une expérience courte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui permet d’appliquer le principe en classe.', 7),
    ('a5eaced2-963c-5f2b-baeb-9ce0026ac733'::uuid, '90ce17e6-fbc7-506b-9e50-d425f48221b7'::uuid, 'Quel savant a le premier formulé l’idée d’inertie ?', 'mcq', '["Galilée","Aristote","Kepler","Archimède"]'::jsonb, 0, 'Newton en fera ensuite sa première loi.', 8),
    ('55bc9e0c-ac08-5f7d-8286-34a2eae6ae9c'::uuid, 'f18dd46f-b39c-54d4-aa9b-da1ba95b610c'::uuid, 'Qu’est-ce qui produit un son ?', 'mcq', '["Un objet qui vibre","Un objet chaud","Un objet chargé électriquement","Un objet en chute libre"]'::jsonb, 0, 'La vibration met en mouvement les molécules voisines.', 1),
    ('de2e2d11-846d-5134-b18c-8632c98bf415'::uuid, 'f18dd46f-b39c-54d4-aa9b-da1ba95b610c'::uuid, 'Le son se propage-t-il dans le vide ?', 'mcq', '["Non, il lui faut un milieu matériel","Oui, comme la lumière","Oui, mais plus lentement","Seulement les ultrasons"]'::jsonb, 0, 'Sans matière, aucune vibration à transmettre.', 2),
    ('4ddcb0fe-6f78-5110-837c-49a8c47ecbbb'::uuid, 'f18dd46f-b39c-54d4-aa9b-da1ba95b610c'::uuid, 'Le son transporte-t-il de la matière ?', 'mcq', '["Non, seulement de l’énergie de proche en proche","Oui, l’air se déplace avec lui","Oui, dans les solides seulement","Oui, à faible distance"]'::jsonb, 0, 'Chaque molécule oscille autour de sa position d’équilibre.', 3),
    ('240332ee-02b5-5386-a2db-05c57fdf59fc'::uuid, 'f18dd46f-b39c-54d4-aa9b-da1ba95b610c'::uuid, 'Quelle est la célérité du son dans l’air à 20 °C ?', 'mcq', '["Environ 340 m·s⁻¹","Environ 1 500 m·s⁻¹","Environ 3,0 × 10⁸ m·s⁻¹","Environ 34 m·s⁻¹"]'::jsonb, 0, 'Elle vaut environ 1 500 m·s⁻¹ dans l’eau.', 4),
    ('fe4c486e-e7c7-5380-8ae9-1caee3ecdeaa'::uuid, 'f18dd46f-b39c-54d4-aa9b-da1ba95b610c'::uuid, 'Dans quel milieu le son se propage-t-il le plus vite ?', 'mcq', '["Dans l’acier","Dans l’air","Dans l’eau","Dans le vide"]'::jsonb, 0, 'La célérité augmente avec la densité et la rigidité du milieu.', 5),
    ('bb273493-55e7-58f9-b3b0-b55c3b86d3eb'::uuid, 'f18dd46f-b39c-54d4-aa9b-da1ba95b610c'::uuid, 'Comment calcule-t-on une distance par la méthode de l’écho ?', 'mcq', '["d = v × Δt / 2","d = v × Δt","d = 2 × v × Δt","d = Δt / v"]'::jsonb, 0, 'La durée mesurée correspond à un aller-retour.', 6),
    ('d8654fe1-98ae-5b2c-9679-17c0e36dfa6b'::uuid, 'f18dd46f-b39c-54d4-aa9b-da1ba95b610c'::uuid, 'Quelle technique médicale utilise les ultrasons ?', 'mcq', '["L’échographie","La radiographie","L’IRM","La scintigraphie"]'::jsonb, 0, 'Elle repose sur le même principe que le sonar.', 7),
    ('7e088e1e-71c4-517e-b469-d39f864af400'::uuid, 'f18dd46f-b39c-54d4-aa9b-da1ba95b610c'::uuid, 'Pourquoi voit-on l’éclair avant d’entendre le tonnerre ?', 'mcq', '["Parce que la lumière se propage beaucoup plus vite que le son","Parce que l’éclair se produit avant","Parce que le son part plus tard","Parce que l’oreille est plus lente que l’œil"]'::jsonb, 0, 'On estime la distance de l’orage en comptant les secondes.', 8),
    ('ce59ab06-05f0-5bda-bb3c-eca7e08e525c'::uuid, 'e1c5de6c-8e51-5460-8baa-dc232bb2012c'::uuid, 'Quelle relation lie période et fréquence ?', 'mcq', '["f = 1 / T","f = T","f = T²","f = 2 × T"]'::jsonb, 0, 'La fréquence s’exprime en hertz.', 1),
    ('944e3d71-f1ec-5a1d-a28d-59797c3dbf85'::uuid, 'e1c5de6c-8e51-5460-8baa-dc232bb2012c'::uuid, 'Quelle fréquence correspond à une période de 2,0 ms ?', 'mcq', '["500 Hz","2 000 Hz","50 Hz","20 Hz"]'::jsonb, 0, 'f = 1 / (2,0 × 10⁻³) = 500 Hz.', 2),
    ('2a3ce4b9-3128-5687-b946-77b1112ffd8f'::uuid, 'e1c5de6c-8e51-5460-8baa-dc232bb2012c'::uuid, 'À quelle grandeur physique la hauteur d’un son est-elle liée ?', 'mcq', '["À la fréquence","À l’intensité","À la durée","À la célérité"]'::jsonb, 0, 'Plus la fréquence est grande, plus le son est aigu.', 3),
    ('3ad86bb3-ccd1-553e-8754-5d77a7398f24'::uuid, 'e1c5de6c-8e51-5460-8baa-dc232bb2012c'::uuid, 'Quel est le domaine des fréquences audibles par l’humain ?', 'mcq', '["Environ de 20 Hz à 20 000 Hz","De 0 à 100 Hz","De 1 000 à 100 000 Hz","De 20 000 à 200 000 Hz"]'::jsonb, 0, 'En dessous, les infrasons ; au-dessus, les ultrasons.', 4),
    ('29dae137-704b-50bb-afaf-0cd91417dd93'::uuid, 'e1c5de6c-8e51-5460-8baa-dc232bb2012c'::uuid, 'Qu’est-ce que le timbre d’un son ?', 'mcq', '["Ce qui permet de distinguer deux instruments jouant la même note","La hauteur du son","Le niveau sonore","La durée de la note"]'::jsonb, 0, 'Il est lié à la présence d’harmoniques.', 5),
    ('f7707154-bdd6-5b51-85bf-f8733c280e2e'::uuid, 'e1c5de6c-8e51-5460-8baa-dc232bb2012c'::uuid, 'Dans quelle unité exprime-t-on le niveau d’intensité sonore ?', 'mcq', '["Le décibel","Le hertz","Le watt","Le newton"]'::jsonb, 0, 'L’échelle des décibels est logarithmique.', 6),
    ('b137207b-fe90-5797-8a16-f2b2cc43be28'::uuid, 'e1c5de6c-8e51-5460-8baa-dc232bb2012c'::uuid, 'Que signifie une augmentation de 10 dB ?', 'mcq', '["L’intensité sonore est multipliée par 10","L’intensité est multipliée par 2","L’intensité augmente de 10 W·m⁻²","La fréquence est multipliée par 10"]'::jsonb, 0, 'Le son est perçu environ deux fois plus fort.', 7),
    ('b43dbf22-2a67-5b5e-8ad6-a1f96695467f'::uuid, 'e1c5de6c-8e51-5460-8baa-dc232bb2012c'::uuid, 'Les cellules ciliées détruites par une exposition sonore excessive se régénèrent avec le temps.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La perte d’audition et les acouphènes sont irréversibles.', 8),
    ('9663e3df-ca9d-5bc4-ad81-46a8ed07fc7f'::uuid, '29c584a1-8a28-53ca-a454-a0b915b7128b'::uuid, 'Comment branche-t-on un ampèremètre ?', 'mcq', '["En série, pour être traversé par le courant","En dérivation aux bornes du dipôle","À la place du générateur","Entre deux nœuds"]'::jsonb, 0, 'Le voltmètre, lui, se branche en dérivation.', 1),
    ('d647919d-cf41-50f2-ace6-a8ba51551fee'::uuid, '29c584a1-8a28-53ca-a454-a0b915b7128b'::uuid, 'Dans quelle unité se mesure une tension ?', 'mcq', '["Le volt","L’ampère","L’ohm","Le watt"]'::jsonb, 0, 'L’intensité se mesure en ampères.', 2),
    ('625a4c58-d67c-5b0a-9bc8-cdfd6982981e'::uuid, '29c584a1-8a28-53ca-a454-a0b915b7128b'::uuid, 'Que dit la loi des nœuds ?', 'mcq', '["La somme des intensités entrantes égale la somme des intensités sortantes","La somme des tensions d’une maille est nulle","L’intensité est proportionnelle à la tension","La tension est la même dans tout le circuit"]'::jsonb, 0, 'Elle traduit la conservation de la charge.', 3),
    ('1bf7499b-741b-5fa0-95f8-77f223f7fd66'::uuid, '29c584a1-8a28-53ca-a454-a0b915b7128b'::uuid, 'Dans un circuit série, comment varie l’intensité ?', 'mcq', '["Elle est la même partout","Elle diminue à chaque dipôle","Elle se partage entre les dipôles","Elle augmente vers le générateur"]'::jsonb, 0, 'Conséquence directe de la loi des nœuds.', 4),
    ('7452118f-2c05-567e-9492-529e9a13dbd1'::uuid, '29c584a1-8a28-53ca-a454-a0b915b7128b'::uuid, 'Que dit la loi des mailles ?', 'mcq', '["La somme algébrique des tensions le long d’une maille est nulle","Les intensités s’additionnent dans une maille","La tension augmente à chaque nœud","Les tensions se multiplient"]'::jsonb, 0, 'Dans un circuit série, la tension du générateur est la somme de celles des récepteurs.', 5),
    ('580874cf-7600-5b7f-8377-25ae12d0760b'::uuid, '29c584a1-8a28-53ca-a454-a0b915b7128b'::uuid, 'Deux lampes en dérivation sous 6,0 V : quelle tension reçoit chacune ?', 'mcq', '["6,0 V","3,0 V","12 V","Cela dépend de leur résistance"]'::jsonb, 0, 'Les branches entre deux mêmes nœuds ont la même tension.', 6),
    ('cb384fd3-b670-580b-a998-f7894d768d6f'::uuid, '29c584a1-8a28-53ca-a454-a0b915b7128b'::uuid, 'Deux branches en dérivation traversées par 0,20 A et 0,30 A : que débite le générateur ?', 'mcq', '["0,50 A","0,10 A","0,25 A","0,06 A"]'::jsonb, 0, 'Par application de la loi des nœuds.', 7),
    ('9f2ad8fa-5fd9-5a58-8284-2db1c366a9cf'::uuid, '29c584a1-8a28-53ca-a454-a0b915b7128b'::uuid, 'L’éclairage domestique est câblé en série.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est câblé en dérivation, pour que chaque lampe reçoive la même tension.', 8),
    ('3bea8be0-119e-5dbc-a334-8b71e3d0c841'::uuid, 'ef6df1ec-ca17-51a7-a186-a2c45f0eb894'::uuid, 'Quelle est l’expression de la loi d’Ohm ?', 'mcq', '["U = R × I","U = I / R","R = U × I","I = U × R"]'::jsonb, 0, 'Avec U en volts, I en ampères, R en ohms.', 1),
    ('c03c0fec-a2ae-5a75-83ee-7990baf7d72c'::uuid, 'ef6df1ec-ca17-51a7-a186-a2c45f0eb894'::uuid, 'Quelle est l’unité de la résistance ?', 'mcq', '["L’ohm","Le volt","L’ampère","Le watt"]'::jsonb, 0, 'Symbole Ω.', 2),
    ('da20e097-da50-5818-8c2c-e617ef2424f0'::uuid, 'ef6df1ec-ca17-51a7-a186-a2c45f0eb894'::uuid, 'Quelle est l’allure de la caractéristique U = f(I) d’un conducteur ohmique ?', 'mcq', '["Une droite passant par l’origine","Une parabole","Une courbe croissante puis décroissante","Une droite ne passant pas par l’origine"]'::jsonb, 0, 'Son coefficient directeur est la résistance.', 3),
    ('d19e8d3e-a5b7-5147-8cd8-a39d7c786a4d'::uuid, 'ef6df1ec-ca17-51a7-a186-a2c45f0eb894'::uuid, 'Une lampe est-elle un conducteur ohmique ?', 'mcq', '["Non, sa résistance augmente avec la température","Oui, comme un résistor","Oui, si la tension est faible","Cela dépend de la couleur du filament"]'::jsonb, 0, 'Sa caractéristique n’est pas une droite.', 4),
    ('354bf6a4-b69a-5bb8-aba4-506f074f879a'::uuid, 'ef6df1ec-ca17-51a7-a186-a2c45f0eb894'::uuid, 'Comment la résistance d’un fil varie-t-elle avec sa longueur ?', 'mcq', '["Elle augmente quand la longueur augmente","Elle diminue quand la longueur augmente","Elle ne dépend pas de la longueur","Elle est proportionnelle au carré de la longueur"]'::jsonb, 0, 'Elle diminue en revanche quand la section augmente.', 5),
    ('09e29fe8-433f-5c02-b6f3-591f7e1f872e'::uuid, 'ef6df1ec-ca17-51a7-a186-a2c45f0eb894'::uuid, 'Qu’est-ce que l’effet Joule ?', 'mcq', '["L’échauffement d’un conducteur parcouru par un courant","La production d’un champ magnétique","La chute de tension aux bornes d’un générateur","La perte d’électrons d’un métal"]'::jsonb, 0, 'Recherché dans un radiateur, subi dans un processeur.', 6),
    ('bed0d5c8-7079-5fc9-8b32-b91ac5cd3105'::uuid, 'ef6df1ec-ca17-51a7-a186-a2c45f0eb894'::uuid, 'Quelle est l’expression de la puissance électrique ?', 'mcq', '["P = U × I","P = U / I","P = U + I","P = U² × I"]'::jsonb, 0, 'Pour un conducteur ohmique, on a aussi P = R × I².', 7),
    ('f04b3d89-a44a-53ab-b248-0b81b197eee8'::uuid, 'ef6df1ec-ca17-51a7-a186-a2c45f0eb894'::uuid, 'Pourquoi le danger électrique augmente-t-il avec les mains mouillées ?', 'mcq', '["Parce que la résistance du corps diminue, donc l’intensité augmente","Parce que la tension augmente","Parce que l’eau produit du courant","Parce que la puissance diminue"]'::jsonb, 0, 'C’est une application directe de la loi d’Ohm.', 8),
    ('800aad99-85d9-5d81-8d7d-058650ba3743'::uuid, '3e96bdc3-33b3-581f-8ede-b6bd8e01437f'::uuid, 'Dans quel type de milieu la lumière se propage-t-elle en ligne droite ?', 'mcq', '["Un milieu transparent et homogène","Un milieu opaque","Un milieu quelconque","Uniquement dans le vide"]'::jsonb, 0, 'C’est le principe de propagation rectiligne.', 1),
    ('deaf7a65-77d4-5ff8-ae9b-09a7a9e04fd7'::uuid, '3e96bdc3-33b3-581f-8ede-b6bd8e01437f'::uuid, 'Quelle est la vitesse de la lumière dans le vide ?', 'mcq', '["3,00 × 10⁸ m·s⁻¹","3,00 × 10⁵ m·s⁻¹","340 m·s⁻¹","1,5 × 10³ m·s⁻¹"]'::jsonb, 0, 'Elle est plus faible dans un milieu matériel.', 2),
    ('f3b72f20-9498-5549-a580-3538fab5d5f5'::uuid, '3e96bdc3-33b3-581f-8ede-b6bd8e01437f'::uuid, 'Qu’est-ce qu’une année-lumière ?', 'mcq', '["La distance parcourue par la lumière en un an","La durée d’un trajet lumineux","Une unité de temps astronomique","La distance Terre-Soleil"]'::jsonb, 0, 'Environ 9,5 × 10¹⁵ mètres.', 3),
    ('1f5523b6-0fd2-58dd-bcf9-ab3b7660820d'::uuid, '3e96bdc3-33b3-581f-8ede-b6bd8e01437f'::uuid, 'Quelle différence entre une source primaire et un objet diffusant ?', 'mcq', '["La source primaire produit sa lumière, l’objet diffusant la renvoie","L’objet diffusant est toujours plus lumineux","La source primaire est toujours chaude","Il n’y a pas de différence"]'::jsonb, 0, 'La Lune est un objet diffusant, le Soleil une source primaire.', 4),
    ('3cc1628f-a0d1-581d-90f2-ce9e15f69aaf'::uuid, '3e96bdc3-33b3-581f-8ede-b6bd8e01437f'::uuid, 'Que produit un prisme éclairé par de la lumière blanche ?', 'mcq', '["Un spectre continu du rouge au violet","Une seule radiation","Une ombre nette","Un rayonnement infrarouge"]'::jsonb, 0, 'La lumière blanche est une superposition de radiations.', 5),
    ('891ff65f-3672-511e-86b5-9acd7b3ad7df'::uuid, '3e96bdc3-33b3-581f-8ede-b6bd8e01437f'::uuid, 'Quel est approximativement le domaine des longueurs d’onde visibles ?', 'mcq', '["De 400 nm à 800 nm","De 100 nm à 200 nm","De 1 mm à 1 cm","De 800 nm à 1 600 nm"]'::jsonb, 0, 'En dessous les UV, au-dessus les infrarouges.', 6),
    ('fcc2543b-a893-5709-8125-0c734694d60d'::uuid, '3e96bdc3-33b3-581f-8ede-b6bd8e01437f'::uuid, 'Qu’est-ce qu’une lumière monochromatique ?', 'mcq', '["Une lumière constituée d’une seule radiation","Une lumière blanche","Une lumière de faible intensité","Une lumière invisible"]'::jsonb, 0, 'Un laser en est le meilleur exemple.', 7),
    ('2b86f89a-84b9-542f-b3a1-23cc01c9c862'::uuid, '3e96bdc3-33b3-581f-8ede-b6bd8e01437f'::uuid, 'Un gaz chaud à basse pression donne un spectre continu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il donne un spectre de raies d’émission, caractéristique de l’élément.', 8),
    ('c95b01a9-83a6-580d-9dd0-4e09539ebdf0'::uuid, '84a0e71f-c02f-591e-ab52-90414eb7246f'::uuid, 'Par rapport à quoi mesure-t-on les angles en optique ?', 'mcq', '["Par rapport à la normale à la surface","Par rapport à la surface elle-même","Par rapport au rayon réfléchi","Par rapport à l’horizontale"]'::jsonb, 0, 'C’est l’erreur la plus fréquente en exercice.', 1),
    ('6d682ea8-a0d3-5ccb-9923-61b69bab4fcb'::uuid, '84a0e71f-c02f-591e-ab52-90414eb7246f'::uuid, 'Que dit la loi de la réflexion ?', 'mcq', '["L’angle de réflexion est égal à l’angle d’incidence","L’angle de réflexion est le double de l’angle d’incidence","Le rayon réfléchi est perpendiculaire au rayon incident","Le rayon réfléchi suit la normale"]'::jsonb, 0, 'Les deux rayons sont dans le plan d’incidence.', 2),
    ('091ed583-fed2-5096-abf9-80da64cbf392'::uuid, '84a0e71f-c02f-591e-ab52-90414eb7246f'::uuid, 'Quelle est l’expression de la loi de Snell-Descartes pour la réfraction ?', 'mcq', '["n₁ × sin i₁ = n₂ × sin i₂","n₁ × i₁ = n₂ × i₂","sin i₁ / sin i₂ = n₁ × n₂","n₁ / sin i₁ = n₂ / sin i₂"]'::jsonb, 0, 'n est l’indice de réfraction du milieu.', 3),
    ('ff90142c-f821-54a2-8b02-05d9885abf16'::uuid, '84a0e71f-c02f-591e-ab52-90414eb7246f'::uuid, 'Que vaut approximativement l’indice de réfraction de l’eau ?', 'mcq', '["1,33","1,00","0,75","2,42"]'::jsonb, 0, 'Celui de l’air vaut 1,00, celui du verre environ 1,5.', 4),
    ('04b66b3b-3251-5e5a-ba2f-a990739f296e'::uuid, '84a0e71f-c02f-591e-ab52-90414eb7246f'::uuid, 'Que se passe-t-il quand un rayon entre dans un milieu plus réfringent ?', 'mcq', '["Il se rapproche de la normale","Il s’écarte de la normale","Il n’est pas dévié","Il est totalement réfléchi"]'::jsonb, 0, 'Il s’en écarte en sortant du milieu plus réfringent.', 5),
    ('1797ed2d-27a9-5978-b41c-ad7a97259345'::uuid, '84a0e71f-c02f-591e-ab52-90414eb7246f'::uuid, 'Sur quel phénomène repose la fibre optique ?', 'mcq', '["La réflexion totale","La dispersion","La diffraction","L’absorption"]'::jsonb, 0, 'Au-delà de l’angle limite, toute la lumière est réfléchie.', 6),
    ('29313be9-5937-5f56-9906-76ad6bb96da0'::uuid, '84a0e71f-c02f-591e-ab52-90414eb7246f'::uuid, 'Pourquoi un prisme disperse-t-il la lumière blanche ?', 'mcq', '["Parce que l’indice de réfraction dépend de la longueur d’onde","Parce que le verre est coloré","Parce que la lumière ralentit","Parce que le prisme est triangulaire"]'::jsonb, 0, 'Le violet est plus dévié que le rouge.', 7),
    ('1de4474e-fb09-5780-87b7-f3236bea9465'::uuid, '84a0e71f-c02f-591e-ab52-90414eb7246f'::uuid, 'Une réflexion diffuse se produit sur une surface parfaitement polie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle se produit sur une surface rugueuse ; le miroir donne une réflexion spéculaire.', 8),
    ('5364ebff-3a9a-5c42-a8f0-b0b2b03d7a36'::uuid, '4c3e78d3-37e4-59ca-8617-c5e4325667d5'::uuid, 'Comment reconnaît-on une lentille convergente ?', 'mcq', '["Elle est plus épaisse au centre qu’aux bords","Elle est plus fine au centre","Elle est plane","Elle est teintée"]'::jsonb, 0, 'Elle fait converger un faisceau parallèle.', 1),
    ('cf6ba6af-7959-5694-9de7-d74d07398450'::uuid, '4c3e78d3-37e4-59ca-8617-c5e4325667d5'::uuid, 'Qu’est-ce que le foyer image F′ ?', 'mcq', '["Le point où convergent les rayons arrivant parallèlement à l’axe optique","Le centre de la lentille","Le point où se trouve l’objet","Le point de l’écran"]'::jsonb, 0, 'La distance OF′ est la distance focale.', 2),
    ('258323cf-6927-5c51-8062-71ea06634bde'::uuid, '4c3e78d3-37e4-59ca-8617-c5e4325667d5'::uuid, 'Quelle est l’expression de la vergence ?', 'mcq', '["C = 1 / f′","C = f′","C = f′²","C = 2 × f′"]'::jsonb, 0, 'Elle s’exprime en dioptries, avec f′ en mètres.', 3),
    ('12c7274e-aedf-5d1f-8ed6-c0a8ac79a3e8'::uuid, '4c3e78d3-37e4-59ca-8617-c5e4325667d5'::uuid, 'Quelle est la distance focale d’une lentille de vergence 5 δ ?', 'mcq', '["0,20 m","5 m","0,05 m","2,0 m"]'::jsonb, 0, 'f′ = 1 / 5 = 0,20 m.', 4),
    ('4d6adba5-960d-5d99-b7c8-9b886179b5e1'::uuid, '4c3e78d3-37e4-59ca-8617-c5e4325667d5'::uuid, 'Que devient un rayon passant par le centre optique ?', 'mcq', '["Il n’est pas dévié","Il repart parallèle à l’axe","Il passe par F′","Il est réfléchi"]'::jsonb, 0, 'C’est l’un des trois rayons particuliers.', 5),
    ('baaf5d42-0f01-5e70-90af-a8057f157dd3'::uuid, '4c3e78d3-37e4-59ca-8617-c5e4325667d5'::uuid, 'Que devient un rayon arrivant parallèlement à l’axe optique ?', 'mcq', '["Il repart en passant par le foyer image F′","Il n’est pas dévié","Il repart par le foyer objet F","Il est absorbé"]'::jsonb, 0, 'C’est la définition même du foyer image.', 6),
    ('e33f1479-cce5-5e19-82cf-67ca0e67eeb3'::uuid, '4c3e78d3-37e4-59ca-8617-c5e4325667d5'::uuid, 'Quel élément de l’œil joue le rôle de lentille convergente ?', 'mcq', '["Le cristallin","La rétine","L’iris","La cornée uniquement"]'::jsonb, 0, 'La rétine joue le rôle de l’écran.', 7),
    ('9c714398-5071-550e-9a73-bb1ac6d685fc'::uuid, '4c3e78d3-37e4-59ca-8617-c5e4325667d5'::uuid, 'Par quel type de lentille corrige-t-on la myopie ?', 'mcq', '["Une lentille divergente","Une lentille convergente","Un prisme","Un miroir"]'::jsonb, 0, 'Chez le myope, l’image se forme en avant de la rétine.', 8),
    ('852fd53e-7748-5e30-9da4-0157bec96a18'::uuid, 'ac1fe737-4bf3-5679-a45c-cf4dc3cf21c9'::uuid, 'Combien de rayons particuliers suffisent à construire une image ?', 'mcq', '["Deux","Un seul","Trois obligatoirement","Quatre"]'::jsonb, 0, 'Le troisième sert de vérification.', 1),
    ('955bedb9-8b24-54e5-8083-90f9d7797715'::uuid, 'ac1fe737-4bf3-5679-a45c-cf4dc3cf21c9'::uuid, 'Où se forme l’image si l’objet est au-delà du foyer objet F ?', 'mcq', '["De l’autre côté de la lentille, réelle et renversée","Du même côté, virtuelle et droite","Au foyer image exactement","À l’infini"]'::jsonb, 0, 'On peut la recueillir sur un écran.', 2),
    ('f29e3a02-cba4-51f9-a7c4-9b999acb7e4f'::uuid, 'ac1fe737-4bf3-5679-a45c-cf4dc3cf21c9'::uuid, 'Quelle image obtient-on avec une loupe ?', 'mcq', '["Une image virtuelle, droite et agrandie","Une image réelle renversée","Une image réelle réduite","Aucune image"]'::jsonb, 0, 'L’objet est placé entre le foyer objet et la lentille.', 3),
    ('1f8c8fae-cbcc-5c97-b5be-5d9b420899d5'::uuid, 'ac1fe737-4bf3-5679-a45c-cf4dc3cf21c9'::uuid, 'Quelle est la relation de conjugaison ?', 'mcq', '["1/OA′ − 1/OA = 1/OF′","1/OA′ + 1/OA = 1/OF′","OA′ − OA = OF′","OA′ × OA = OF′"]'::jsonb, 0, 'Avec des mesures algébriques sur l’axe orienté.', 4),
    ('dcc0200e-f918-5095-9fa2-d85c9569923f'::uuid, 'ac1fe737-4bf3-5679-a45c-cf4dc3cf21c9'::uuid, 'Comment calcule-t-on le grandissement ?', 'mcq', '["γ = A′B′/AB = OA′/OA","γ = AB/A′B′","γ = OA/OF′","γ = OA × OA′"]'::jsonb, 0, 'Un grandissement négatif signale une image renversée.', 5),
    ('05afe2ed-86e0-5816-bd3d-8609b49e197e'::uuid, 'ac1fe737-4bf3-5679-a45c-cf4dc3cf21c9'::uuid, 'Que signifie un grandissement de −0,5 ?', 'mcq', '["L’image est renversée et deux fois plus petite","L’image est droite et deux fois plus grande","L’image est virtuelle","L’image est à l’infini"]'::jsonb, 0, 'Le signe donne le sens, la valeur absolue la taille.', 6),
    ('7406c41e-b870-5279-b3ac-1ab4e4406b56'::uuid, 'ac1fe737-4bf3-5679-a45c-cf4dc3cf21c9'::uuid, 'L’image formée sur la rétine par l’œil est droite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est réelle et renversée ; c’est le cerveau qui la redresse.', 7),
    ('9721da92-3b5c-5d75-af5d-fe21672834b7'::uuid, 'ac1fe737-4bf3-5679-a45c-cf4dc3cf21c9'::uuid, 'Quel dispositif forme une image réelle agrandie ?', 'mcq', '["Le vidéoprojecteur","La loupe","L’appareil photo","Le télescope à l’oculaire"]'::jsonb, 0, 'L’objet y est placé juste au-delà du foyer objet.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('physique-chimie');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('physique-chimie')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 289 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 289 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
